import java.util.Scanner;

public class LuckyTickets {

    private static final int MOD = 998244353;
    private static final int twoPow = 23;
    private static final int ROOT = 15311432;

    private static int bitReverse(int n, int k) {
        int rev = 0;
        for (int i = 0; i < k; i++) {
            rev = (rev << 1) | (n & 1);
            n >>= 1;
        }
        return rev;
    }

    private static long powMod(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    private static long invMod(long a) {
        return powMod(a, MOD - 2);
    }

    private static long[] roots(int k, boolean inverse) {
        long root = powMod(ROOT, powMod(2, twoPow - k));
        if (inverse) {
            root = invMod(root);
        }
        long[] rootsArr = new long[k];
        if (k > 0) {
            rootsArr[k - 1] = root;
        }
        for (int i = k - 1; i > 0; i--) {
            rootsArr[i - 1] = (rootsArr[i] * rootsArr[i]) % MOD;
        }
        return rootsArr;
    }

    private static long[] reorderArray(long[] a, int k) {
        long[] ans = new long[a.length];
        for (int i = 0; i < a.length; i++) {
            ans[bitReverse(i, k)] = a[i];
        }
        return ans;
    }

    private static long[] ntt(long[] coef, int k, boolean inverse) {
        coef = reorderArray(coef, k);
        long[] rootsArr = roots(k, inverse);
        for (int s = 0; s < k; s++) {
            int len = 1 << s;
            for (int start = 0; start < coef.length; start += 2 * len) {
                long curRoot = 1;
                for (int j = start; j < start + len; j++) {
                    long t = (curRoot * coef[j + len]) % MOD;
                    long u = coef[j];
                    coef[j] = (u + t) % MOD;
                    coef[j + len] = (u - t + MOD) % MOD;
                    curRoot = (rootsArr[s] * curRoot) % MOD;
                }
            }
        }
        return coef;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int m = sc.nextInt();
        int[] nums = new int[m];
        int maxVal = 0;
        for (int i = 0; i < m; i++) {
            nums[i] = sc.nextInt();
            maxVal = Math.max(maxVal, nums[i]);
        }
        int minSize = n * maxVal + 1;
        int size = 1;
        int k = 0;
        while (size < minSize) {
            size <<= 1;
            k++;
        }
        long[] a = new long[size];
        for (int i = 0; i < nums.length; i++) {
            a[nums[i]] = 1;
        }
        a = ntt(a, k, false);
        for (int i = 0; i < size; i++) {
            a[i] = powMod(a[i], n);
        }
        a = ntt(a, k, true);
        long sumAns = 0;
        for (int i = 0; i < size; i++) {
            sumAns = (sumAns + a[i] * a[i]) % MOD;
        }
        long invSize = invMod(size);
        System.out.println((((sumAns * invSize) % MOD) * invSize) % MOD);
    }
}
